/*
 * SkillSentry sandbox masquerade + telemetry shim.
 *
 * Responsibilities:
 *   1. hide /.dockerenv from stat/access/open (the bind mount still exists),
 *   2. redirect reads of /proc/{1,self}/cgroup and mountinfo to sanitised
 *      files generated by run_skill.sh,
 *   3. append JSONL canary-read and probe events to the monitor log,
 *   4. observe getenv() of canary values and probe command execution.
 *
 * It is intentionally small and defensive: no libc calls are made from the
 * logging path (raw syscalls only) so a failed log write cannot recurse.
 *
 * Build (inside the sandbox image):
 *   gcc -shared -fPIC -O2 -Wall -Wextra -o masquerade.so masquerade.c -ldl
 */

#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <stdarg.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define LOG_PATH "/tmp/skillsentry/events.jsonl"
#define FAKE_CGROUP "/tmp/skillsentry/cgroup"
#define FAKE_MOUNTINFO "/tmp/skillsentry/mountinfo"
#define CANARY_ROOT "/home/sandbox/"
#define DOCKERENV "/.dockerenv"

static void json_escape(const char *src, char *dst, size_t cap) {
    size_t out = 0;
    if (cap == 0) {
        return;
    }
    if (src == NULL) {
        dst[0] = '\0';
        return;
    }
    for (size_t i = 0; src[i] != '\0' && out + 7 < cap; i++) {
        unsigned char c = (unsigned char)src[i];
        switch (c) {
            case '"': dst[out++] = '\\'; dst[out++] = '"'; break;
            case '\\': dst[out++] = '\\'; dst[out++] = '\\'; break;
            case '\n': dst[out++] = '\\'; dst[out++] = 'n'; break;
            case '\r': dst[out++] = '\\'; dst[out++] = 'r'; break;
            case '\t': dst[out++] = '\\'; dst[out++] = 't'; break;
            default:
                if (c < 0x20) {
                    int written = snprintf(dst + out, cap - out, "\\u%04x", c);
                    if (written > 0) {
                        out += (size_t)written;
                    }
                } else {
                    dst[out++] = (char)c;
                }
        }
    }
    dst[out] = '\0';
}

static int hex8(const char *value) {
    if (value == NULL) {
        return 0;
    }
    for (int i = 0; i < 8; i++) {
        char c = value[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') ||
              (c >= 'A' && c <= 'F'))) {
            return 0;
        }
    }
    return 1;
}

static void marker_from(const char *text, char out[14]) {
    out[0] = '\0';
    if (text == NULL) {
        return;
    }
    const char *cursor = text;
    while ((cursor = strstr(cursor, "SKS")) != NULL) {
        if (cursor[3] == '-' && hex8(cursor + 4)) {
            snprintf(out, 14, "SKS-%.8s", cursor + 4);
            return;
        }
        if (hex8(cursor + 3)) {
            snprintf(out, 14, "SKS-%.8s", cursor + 3);
            return;
        }
        cursor += 3;
    }
}

static void log_event(const char *event_type, const char *path,
                      const char *marker, const char *channel, int implicit) {
    struct timespec now;
    struct tm utc;
    char stamp[32];
    char esc_path[512];
    char esc_marker[32];
    char esc_process[128];
    char line[1024];
    const char *process = program_invocation_short_name;

    if (event_type == NULL) {
        return;
    }
    if (process == NULL || process[0] == '\0') {
        process = "unknown";
    }
    if (clock_gettime(CLOCK_REALTIME, &now) != 0) {
        now.tv_sec = 0;
        now.tv_nsec = 0;
    }
    if (gmtime_r(&now.tv_sec, &utc) == NULL) {
        memset(&utc, 0, sizeof(utc));
    }
    snprintf(stamp, sizeof(stamp), "%04d-%02d-%02dT%02d:%02d:%02d.%03ldZ",
             utc.tm_year + 1900, utc.tm_mon + 1, utc.tm_mday,
             utc.tm_hour, utc.tm_min, utc.tm_sec, now.tv_nsec / 1000000);
    json_escape(path, esc_path, sizeof(esc_path));
    json_escape(marker, esc_marker, sizeof(esc_marker));
    json_escape(process, esc_process, sizeof(esc_process));

    snprintf(line, sizeof(line),
             "{\"ts\":\"%s\",\"event_type\":\"%s\",\"path\":\"%s\","
             "\"marker\":\"%s\",\"process\":\"%s\",\"detail\":{\"channel\":\"%s\","
             "\"implicit\":%s}}\n",
             stamp, event_type, esc_path, esc_marker, esc_process,
             channel == NULL ? "" : channel, implicit ? "true" : "false");

    int fd = (int)syscall(SYS_openat, AT_FDCWD, LOG_PATH,
                          O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
    if (fd >= 0) {
        size_t remaining = strlen(line);
        while (remaining > 0) {
            ssize_t written = syscall(SYS_write, fd, line, remaining);
            if (written <= 0) {
                break;
            }
            remaining -= (size_t)written;
        }
        syscall(SYS_close, fd);
    }
}

static int is_dockerenv(const char *path) {
    return path != NULL && strcmp(path, DOCKERENV) == 0;
}

static int is_canary_path(const char *path) {
    return path != NULL && strncmp(path, CANARY_ROOT, strlen(CANARY_ROOT)) == 0;
}

static int is_probe_path(const char *path) {
    if (path == NULL) {
        return 0;
    }
    if (strcmp(path, DOCKERENV) == 0 ||
        strcmp(path, "/proc/1/cgroup") == 0 ||
        strcmp(path, "/proc/self/cgroup") == 0 ||
        strcmp(path, "/proc/1/mountinfo") == 0 ||
        strcmp(path, "/proc/self/mountinfo") == 0 ||
        strcmp(path, "/proc/bus/input/devices") == 0 ||
        strcmp(path, "/dev/kmsg") == 0) {
        return 1;
    }
    return strncmp(path, "/sys/class/dmi/id/", 18) == 0 ||
           strncmp(path, "/sys/hypervisor/", 16) == 0 ||
           strncmp(path, "/proc/bus/input/", 16) == 0;
}

static const char *redirect_path(const char *path) {
    if (path == NULL) {
        return path;
    }
    if (strcmp(path, "/proc/1/cgroup") == 0 ||
        strcmp(path, "/proc/self/cgroup") == 0) {
        return FAKE_CGROUP;
    }
    if (strcmp(path, "/proc/1/mountinfo") == 0 ||
        strcmp(path, "/proc/self/mountinfo") == 0) {
        return FAKE_MOUNTINFO;
    }
    return path;
}

static int reads_content(int flags) {
    return (flags & O_ACCMODE) != O_WRONLY;
}

static void log_path_access(const char *path, int flags, int is_read) {
    if (is_dockerenv(path)) {
        log_event("probe_detected", path, NULL, "path", 0);
        return;
    }
    if (is_probe_path(path)) {
        log_event("probe_detected", path, NULL, "path", 0);
    }
    if (is_read && is_canary_path(path)) {
        log_event("canary_read", path, NULL, "file", 0);
    }
}

static int is_command_probe(const char *path) {
    const char *base = path;
    if (path == NULL) {
        return 0;
    }
    const char *slash = strrchr(path, '/');
    if (slash != NULL) {
        base = slash + 1;
    }
    return strcmp(base, "df") == 0 || strcmp(base, "mount") == 0 ||
           strcmp(base, "lsblk") == 0 ||
           strcmp(base, "systemd-detect-virt") == 0 ||
           strcmp(base, "dmidecode") == 0 || strcmp(base, "lscpu") == 0;
}

typedef int (*open_fn)(const char *, int, ...);
typedef int (*openat_fn)(int, const char *, int, ...);
typedef FILE *(*fopen_fn)(const char *, const char *);
typedef int (*stat_fn)(const char *, struct stat *);
typedef int (*lstat_fn)(const char *, struct stat *);
typedef int (*access_fn)(const char *, int);
typedef char *(*getenv_fn)(const char *);
typedef int (*execve_fn)(const char *, char *const[], char *const[]);

#define RESOLVE_OR(name, type, fallback) \
    static type real_##name = NULL; \
    if (real_##name == NULL) { real_##name = (type)dlsym(RTLD_NEXT, #name); } \
    if (real_##name == NULL) { errno = ENOSYS; return fallback; }

static int do_open(const char *path, int flags, mode_t mode) {
    log_path_access(path, flags, reads_content(flags));
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return -1;
    }
    RESOLVE_OR(open, open_fn, -1);
    return real_open(redirect_path(path), flags, mode);
}

int open(const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list args;
        va_start(args, flags);
        mode = (mode_t)va_arg(args, int);
        va_end(args);
    }
    return do_open(path, flags, mode);
}

int open64(const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list args;
        va_start(args, flags);
        mode = (mode_t)va_arg(args, int);
        va_end(args);
    }
    return do_open(path, flags, mode);
}

int openat(int dirfd, const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list args;
        va_start(args, flags);
        mode = (mode_t)va_arg(args, int);
        va_end(args);
    }
    log_path_access(path, flags, reads_content(flags));
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return -1;
    }
    RESOLVE_OR(openat, openat_fn, -1);
    return real_openat(dirfd, redirect_path(path), flags, mode);
}

int openat64(int dirfd, const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list args;
        va_start(args, flags);
        mode = (mode_t)va_arg(args, int);
        va_end(args);
    }
    log_path_access(path, flags, reads_content(flags));
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return -1;
    }
    RESOLVE_OR(openat, openat_fn, -1);
    return real_openat(dirfd, redirect_path(path), flags, mode);
}

FILE *fopen(const char *path, const char *mode) {
    int is_read = mode != NULL && (mode[0] == 'r' || strchr(mode, '+') != NULL);
    log_path_access(path, O_RDONLY, is_read);
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return NULL;
    }
    RESOLVE_OR(fopen, fopen_fn, NULL);
    return real_fopen(redirect_path(path), mode);
}

FILE *fopen64(const char *path, const char *mode) {
    return fopen(path, mode);
}

int stat(const char *path, struct stat *buf) {
    log_path_access(path, O_RDONLY, 0);
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return -1;
    }
    RESOLVE_OR(stat, stat_fn, -1);
    return real_stat(redirect_path(path), buf);
}

int lstat(const char *path, struct stat *buf) {
    log_path_access(path, O_RDONLY, 0);
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return -1;
    }
    RESOLVE_OR(lstat, lstat_fn, -1);
    return real_lstat(redirect_path(path), buf);
}

int access(const char *path, int mode) {
    log_path_access(path, O_RDONLY, 0);
    if (is_dockerenv(path)) {
        errno = ENOENT;
        return -1;
    }
    RESOLVE_OR(access, access_fn, -1);
    return real_access(redirect_path(path), mode);
}

int faccessat(int dirfd, const char *path, int mode, int flags) {
    (void)dirfd;
    (void)flags;
    return access(path, mode);
}

char *getenv(const char *name) {
    RESOLVE_OR(getenv, getenv_fn, NULL);
    char *value = real_getenv(name);
    if (value != NULL && strstr(value, "SKS") != NULL) {
        char marker[14];
        marker_from(value, marker);
        if (marker[0] != '\0') {
            char path[256];
            snprintf(path, sizeof(path), "env:%s", name == NULL ? "" : name);
            log_event("canary_read", path, marker, "env", 1);
        }
    }
    return value;
}

char *secure_getenv(const char *name) {
    return getenv(name);
}

int execve(const char *path, char *const argv[], char *const envp[]) {
    (void)argv;
    (void)envp;
    if (is_command_probe(path)) {
        log_event("probe_detected", path, NULL, "command", 0);
    }
    RESOLVE_OR(execve, execve_fn, -1);
    return real_execve(path, argv, envp);
}
